-- Generated from the repository CSV files by scripts/generate-societa-migration.mjs
-- Do not execute automatically: review the accompanying audit first.

begin;

create extension if not exists unaccent with schema extensions;

create or replace function public.normalize_societa_name(input text)
returns text
language sql
immutable
strict
set search_path = ''
as $$
  select regexp_replace(lower(extensions.unaccent(input)), '[^a-z0-9]+', '', 'g');
$$;

create table public.societa (
  id integer primary key,
  nome_ufficiale text not null,
  nome_personalizzato text null,
  nome_normalizzato text not null unique,
  squadra_associata text null,
  fantallenatore text null,
  nickname_instagram text null,
  stagione_ingresso text null,
  categoria text null,
  girone text null,
  logo_path text null,
  storia text null,
  badge_tipo text null,
  attiva boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint societa_nome_normalizzato_coerente
    check (nome_normalizzato = public.normalize_societa_name(coalesce(nome_personalizzato, nome_ufficiale)))
);

create table public.societa_alias (
  id bigint generated by default as identity primary key,
  societa_id integer not null references public.societa(id) on delete cascade,
  alias text not null,
  alias_normalizzato text not null,
  fonte text null,
  created_at timestamptz not null default now(),
  constraint societa_alias_normalizzato_coerente
    check (alias_normalizzato = public.normalize_societa_name(alias)),
  constraint societa_alias_societa_normalizzato_unique unique (societa_id, alias_normalizzato)
);

create index societa_alias_alias_normalizzato_idx
  on public.societa_alias (alias_normalizzato);

create or replace function public.set_societa_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger societa_set_updated_at
before update on public.societa
for each row execute function public.set_societa_updated_at();

alter table public.societa enable row level security;
alter table public.societa_alias enable row level security;

revoke all on public.societa from anon, authenticated;
revoke all on public.societa_alias from anon, authenticated;
grant select on public.societa to anon, authenticated;
grant select on public.societa_alias to anon, authenticated;

create policy societa_public_read_active
on public.societa for select
to anon, authenticated
using (attiva = true);

create policy societa_alias_public_read_active
on public.societa_alias for select
to anon, authenticated
using (exists (
  select 1 from public.societa s
  where s.id = societa_alias.societa_id and s.attiva = true
));

insert into public.societa (
  id, nome_ufficiale, nome_personalizzato, nome_normalizzato, squadra_associata,
  fantallenatore, nickname_instagram, stagione_ingresso, categoria, girone,
  logo_path, storia, badge_tipo, attiva
) values
  (1, 'KUNG FU PARMA CALCIO', null, public.normalize_societa_name('KUNG FU PARMA CALCIO'), 'Parma', 'Leonardo Pantisano', 'leos00', '2024/25', 'Serie A', null, '/societa/001_Kungfuparma.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, KUNG FU PARMA CALCIO ha scritto la storia fin dal suo anno d''esordio. Alla prima partecipazione conquista Serie B, Champions League e Coppa Fanta a 20, firmando il primo e, ancora oggi, unico Triplete della competizione. Un''impresa irripetibile che vale l''immediata promozione in Serie A, il primato di società più titolata del Fanta a 20 e lo sblocco dell''emblema Sovrano. La stagione successiva non riesce a confermarsi ai vertici, ma ogni nuova annata viene affrontata con il peso e il prestigio di chi ha già compiuto qualcosa che nessun''altra società è ancora riuscita a eguagliare.', null, true),
  (2, 'Coolinese FC', null, public.normalize_societa_name('Coolinese FC'), 'Udinese', 'Gianluca Antonelli - Marco Prefetto', 'gianlucantonelli - marcoprefetto99', '2023/24', 'Serie A', null, '/societa/002_Coolinese.png', 'Presente fin dalla stagione inaugurale del Fanta a 20, Coolinese FC ha costruito il proprio prestigio con pazienza, continuità e una costante crescita nel tempo. Dopo un promettente quarto posto all''esordio e una stagione difficile, la consacrazione arriva nel 2025/26: conquista il primo storico Scudetto e la Champions League, completando uno straordinario double che la proietta in vetta al Ranking Storico. Più che per i singoli exploit, la Coolinese è diventata il simbolo della continuità, trasformando la costanza di rendimento nella propria firma e affermandosi come una delle grandi potenze del Fanta a 20.', 'campione_in_carica', true),
  (3, 'Analanta', null, public.normalize_societa_name('Analanta'), 'Atalanta', 'Gabriele Isabella - Carlo Cabiati', 'gabriele_isabella_ - carlo_cabiati', '2023/24', 'Serie A', null, '/societa/003_Analanta.png', 'Tra le protagoniste della stagione inaugurale del Fanta a 20, Analanta occupa un posto d''onore nella storia della competizione. È la prima società ad aver conquistato la Serie A, un primato che nessuno potrà mai sottrarle. Dopo aver scritto la pagina iniziale del campionato, ha continuato a lasciare il segno conquistando anche l''Europa League nella stagione 2024/25, confermandosi una presenza costante nelle zone alte della classifica. Pur senza tornare sul tetto d''Italia, il suo nome resta indissolubilmente legato alle origini del Fanta a 20 e alla nascita delle sue prime grandi rivalità.', null, true),
  (4, 'Cagliarithanos', null, public.normalize_societa_name('Cagliarithanos'), 'Cagliari', 'Antonio Lombardi', 'lombi_sins', '2023/24', 'Serie A', null, '/societa/004_Cagliarithanos.png', 'Presente fin dalla stagione inaugurale del Fanta a 20, Cagliarithanos si è affermata come una delle società più solide e competitive della competizione. Il punto più alto della sua storia arriva con la conquista della Champions League nella stagione 2023/24, impresa che consacra il club tra le grandi del Fanta a 20. Negli anni successivi conferma il proprio valore raggiungendo una finale di Europa League e una semifinale di Champions League, dimostrando una costanza di rendimento che poche società possono vantare. Più che per i picchi isolati, Cagliarithanos è diventata il simbolo di una competitività capace di rinnovarsi stagione dopo stagione.', null, true),
  (5, 'IRoman', null, public.normalize_societa_name('IRoman'), 'Roma', 'Francesco Lombardi', 'francelomba8', '2023/24', 'Serie A', null, '/societa/005_Iroman.png', 'Presente fin dalla stagione inaugurale del Fanta a 20, IRoman è una delle società più competitive a non aver ancora conquistato un trofeo ufficiale. Nel corso degli anni ha collezionato piazzamenti di prestigio, spingendosi fino alla finale di Champions League nella stagione 2025/26 e sfiorando più volte il salto definitivo tra le grandi vincitrici della competizione. Alla sua storia è legato anche un primato tanto singolare quanto indesiderato: il fantapunteggio di 31, il più basso mai registrato in una singola giornata del Fanta a 20, record che le è valso l''emblema Abisso. Tra grandi imprese sfiorate e cadute memorabili, IRoman continua a inseguire quel titolo che manca per completare la propria storia.', null, true),
  (6, 'I Leccendari', null, public.normalize_societa_name('I Leccendari'), 'Lecce', 'Francesco Dibilio - Federico Di Rosa', 'francesco_dibilio - federico_di_rosa', '2023/24', 'Serie A', null, '/societa/006_Ileccendari.png', 'Entrati nel Fanta a 20 fin dalla stagione inaugurale, I Leccendari hanno trovato nelle competizioni europee il terreno ideale per costruire la propria storia. La vittoria dell''Europa League nella stagione 2023/24 e quella della Conference League l''anno successivo hanno consacrato il club tra le società più vincenti oltre i confini del campionato. Sul fronte nazionale il miglior risultato arriva nel 2025/26, con uno storico secondo posto in Serie A che lo porta a un passo dal primo Scudetto. Pur senza aver ancora conquistato il titolo italiano, I Leccendari si sono affermati come una delle realtà più temibili e rispettate del panorama europeo del Fanta a 20.', null, true),
  (7, 'Interstellar', null, public.normalize_societa_name('Interstellar'), 'Inter', 'Federico Ravenna', 'federavee', '2023/24', 'Serie A', null, '/societa/007_Interstellar.png', 'Presente nel Fanta a 20 fin dalla stagione inaugurale, Interstellar ha costruito il proprio percorso attraverso una crescita continua. Dopo aver conquistato la Conference League nella stagione d''esordio, il club compie il definitivo salto di qualità nel 2024/25, quando alza al cielo anche la Champions League e si afferma tra le grandi protagoniste della competizione. Pur senza aver ancora raggiunto il vertice in campionato, Interstellar ha dimostrato stagione dopo stagione di poter competere ai massimi livelli, costruendo il proprio prestigio soprattutto sul palcoscenico europeo.', null, true),
  (8, 'Viva la Pisa', null, public.normalize_societa_name('Viva la Pisa'), 'Pisa', 'Francesco Gasparini', 'jason_bromb', '2024/25', 'Serie A', null, '/societa/008_Vivalapisa.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, Viva la Pisa ha saputo imporsi fin dai primi mesi di attività. La promozione conquistata al primo tentativo le spalanca immediatamente le porte della Serie A, dove il club si conferma competitivo con un ottimo sesto posto e una presenza nelle fasi finali della Champions League già alla prima stagione nella massima categoria. Un percorso di crescita rapido e convincente che lascia intravedere margini ancora più importanti per il futuro.', null, true),
  (9, 'Brodena', null, public.normalize_societa_name('Brodena'), 'Modena', 'Francesco Grossi - Lorenzo Ranaldi', 'fra_08 - rana_crac', '2023/24', 'Serie A', null, '/societa/009_Brodena.png', 'La storia di Brodena nel Fanta a 20 è fatta di cadute e ripartenze. Presente fin dalla stagione inaugurale della competizione, il club sorprende tutti conquistando uno straordinario terzo posto nel primo campionato di Serie A. La stagione successiva arriva però l''inattesa retrocessione, cancellata immediatamente dalla promozione ottenuta al primo tentativo. Un percorso fatto di alti e bassi che ha forgiato il carattere della società, capace di reagire alle difficoltà e tornare subito a competere ai massimi livelli.', 'neo_promossa', true),
  (10, 'Bolagna', null, public.normalize_societa_name('Bolagna'), 'Bologna', 'Francesco Capuano', 'capufra', '2023/24', 'Serie A', null, '/societa/010_Bolagna.png', 'Presente nel Fanta a 20 fin dalla stagione inaugurale, Bolagna è una società ancora alla ricerca del primo trofeo della propria storia, ma capace di ritagliarsi un posto speciale negli archivi della competizione. Dopo aver sfiorato il vertice con il terzo posto conquistato in Serie A nella stagione 2024/25, il club ha firmato una delle imprese individuali più incredibili di sempre: il fantapunteggio di 94, il più alto mai registrato in una singola giornata del Fanta a 20, ottenuto nonostante i dieci giocatori andati a voto. Un record ancora imbattuto che gli è valso l''emblema Tiranno e un posto nella storia della competizione.', null, true),
  (11, 'Milantatori', null, public.normalize_societa_name('Milantatori'), 'Milan', 'Stefano Spotorno', 'stefanospotorno', '2023/24', 'Serie A', null, '/societa/011_Milantatori.png', 'La storia di Milantatori nel Fanta a 20 è quella di una continua risalita. Presente fin dalla stagione inaugurale della competizione, il club chiude il suo primo campionato all''ultimo posto, ma trasforma presto quella delusione nel punto di partenza di un percorso di costante crescita. Nel giro di una sola stagione arriva fino al quarto posto in Serie A e raggiunge le fasi finali della Champions League, confermandosi tra le società più competitive della lega. Un''evoluzione costruita con pazienza e continuità, che ha cambiato radicalmente il volto del club.', null, true),
  (12, 'PREDATORINO', null, public.normalize_societa_name('PREDATORINO'), 'Torino', 'Luca Grassini', 'luca_grassini', '2024/25', 'Serie A', null, '/societa/012_Predatorino.png', 'L''ingresso di PREDATORINO nel Fanta a 20, nella stagione 2024/25, non è passato inosservato. Al debutto il club conquista uno straordinario secondo posto in Serie A e raggiunge la finale di Champions League, dimostrando fin da subito di poter competere con le migliori società della competizione. La stagione successiva conferma la propria competitività con un piazzamento nella parte alta della classifica, dando continuità a un progetto che, nonostante la giovane età, si è già ritagliato un ruolo di primo piano nel panorama del Fanta a 20.', null, true),
  (13, 'Como Habilis', null, public.normalize_societa_name('Como Habilis'), 'Como', 'Marco Losno - Matteo Ratti', 'marcolosno - matteo__ratti', '2023/24', 'Serie A', null, '/societa/013_Comohabilis.png', 'La crescita di Como Habilis è stata una delle più costanti del Fanta a 20. Presente fin dalla stagione inaugurale della competizione, il club ha saputo migliorarsi anno dopo anno, passando dalle zone basse della classifica fino a conquistare uno storico terzo posto in Serie A nella stagione 2025/26. Un percorso costruito con pazienza e continuità, che ha trasformato la società in una presenza sempre più credibile e competitiva ai vertici del campionato.', null, true),
  (14, 'Hellas Tronza', null, public.normalize_societa_name('Hellas Tronza'), 'Hellas Verona', 'Alessandro Papaleo', 'heisengrim', '2024/25', 'Serie A', null, '/societa/014_Hellastronza.png', 'La storia di Hellas Tronza nel Fanta a 20 inizia nella stagione 2024/25 e trova subito il suo primo grande momento di gloria. Al debutto il club conquista l''Europa League, entrando immediatamente nell''albo d''oro della competizione. Nella stagione successiva conferma la propria competitività raggiungendo nuovamente le fasi finali del torneo, dimostrando una particolare continuità nelle competizioni europee. Un percorso che ha permesso alla società di ritagliarsi fin da subito un posto tra le realtà più competitive del Fanta a 20.', null, true),
  (15, 'MATERASSUOLO', null, public.normalize_societa_name('MATERASSUOLO'), 'Sassuolo', 'Andrea Scalernio', 'themorningson_', '2024/25', 'Serie A', null, '/societa/015_Materassuolo.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, MATERASSUOLO ha saputo ritagliarsi fin da subito un ruolo da protagonista in Serie B. Il terzo posto conquistato al primo tentativo vale la promozione in Serie A, traguardo raggiunto al termine di una stagione impreziosita anche dal cammino fino ai quarti di Coppa Fanta a 20. L''impatto con la massima categoria si rivela più complicato del previsto, ma il club ha già dimostrato di possedere le qualità e l''ambizione necessarie per costruire il proprio futuro nel Fanta a 20.', null, true),
  (16, 'Cremonelle', null, public.normalize_societa_name('Cremonelle'), 'Cremonese', 'Riccardo Galanti -  Davide Dicandia', 'whos.gala - davide.dicandia', '2024/25', 'Serie A', null, '/societa/016_Cremonelle.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, Cremonelle ha impiegato appena una stagione per affermarsi ai vertici della competizione. Dopo un primo anno utile ad accumulare esperienza, il club sorprende tutti nel 2025/26 chiudendo il campionato di Serie A al quarto posto e conquistando l''Europa League, primo trofeo della propria storia. Un''annata che ha consacrato la società tra le realtà emergenti del Fanta a 20 e lasciato intravedere prospettive ancora più ambiziose.', null, true),
  (17, 'Napolizia', null, public.normalize_societa_name('Napolizia'), 'Napoli', 'Ettore Funaioli - Tommaso Lupo', 'ettofuna - lupo_tommaso', '2023/24', 'Serie A', null, '/societa/017_Napolizia.png', 'La storia di Napolizia nel Fanta a 20 è quella di una società che non ha mai smesso di inseguire il proprio momento. Presente fin dalla stagione inaugurale della competizione, il club ha attraversato annate difficili senza perdere la capacità di rendersi protagonista nelle competizioni europee. Dopo aver sfiorato il titolo con la finale raggiunta nel 2024/25, la consacrazione arriva una stagione più tardi con la conquista della Conference League, primo trofeo della sua storia. Un successo che premia la perseveranza di una società capace di trasformare un percorso fatto di pazienza e determinazione in un trionfo europeo.', null, true),
  (18, 'FiorenToni Pepperoni', null, public.normalize_societa_name('FiorenToni Pepperoni'), 'Fiorentina', 'Tommaso Cherubini - Diego D''Avanzo', 'tommaso.cherubini - davanzo_die.gol', '2024/25', 'Serie A', null, '/societa/018_Fiorentonipepperoni.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, FiorenToni Pepperoni ha dimostrato fin da subito di poter competere nei grandi appuntamenti. Alla prima stagione raggiunge infatti la finale di Coppa Fanta a 20, sfiorando uno dei trofei più prestigiosi dell''intera competizione. Pur senza aver ancora trovato la stessa continuità in campionato, il club ha mostrato qualità e personalità, lasciando la sensazione di poter ambire a traguardi importanti nelle stagioni a venire.', null, true),
  (19, 'VenEzio Greggio Fc', null, public.normalize_societa_name('VenEzio Greggio Fc'), 'Venezia', 'Nicolò Perina', 'nicoloperina', '2024/25', 'Serie A', null, '/societa/019_Veneziogreggio.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, VenEzio Greggio FC ha saputo crescere con continuità fin dai suoi primi passi nella competizione. Dopo un''annata di ambientamento, il club cambia marcia nella stagione successiva, chiudendo il campionato di Serie B al terzo posto e conquistando la promozione in Serie A. Un percorso costruito con pazienza e determinazione, che ha posto basi solide per l''inizio di una nuova avventura nella massima categoria.', 'neo_promossa', true),
  (20, 'SCOREGGIANA', null, public.normalize_societa_name('SCOREGGIANA'), 'Reggiana', 'Lorenzo Micomonaco - Andrea Mazzetti', 'micolollo - una_mas95', '2025/26', 'Serie A', null, '/societa/020_Scoreggiana.png', 'Entrata nel Fanta a 20 nella stagione 2025/26, SCOREGGIANA ha vissuto un debutto che poche società possono vantare. Al primo anno di partecipazione conquista infatti la Serie B e la Champions League, centrando uno straordinario double che le vale l''immediata promozione in Serie A. Un esordio da incorniciare che ha permesso al club di entrare subito nell''albo d''oro della competizione e di presentarsi come una delle società più promettenti del Fanta a 20.', 'neo_promossa', true),
  (21, 'Juventrap', null, public.normalize_societa_name('Juventrap'), 'Juventus', 'Francesco Genna', 'iamfr4g_', '2023/24', 'Serie B', null, '/societa/021_Juventrap.png', 'Per tre stagioni consecutive Juventrap ha fatto parte della Serie A del Fanta a 20, competizione che disputa fin dalla sua stagione inaugurale. Dopo aver chiuso l''annata d''esordio a metà classifica e aver preso parte per due volte alla Champions League, il club vive un progressivo calo culminato con la retrocessione al termine della stagione 2025/26. Una battuta d''arresto che interrompe il suo percorso nella massima categoria, ma che apre un nuovo capitolo con l''obiettivo di riconquistare al più presto la Serie A.', null, true),
  (22, 'Fel-Lazio', null, public.normalize_societa_name('Fel-Lazio'), 'Lazio', 'Pasquale Malatesta - Domenico Mosca', 'thereal_kingmala - moskitovic', '2023/24', 'Serie B', null, '/societa/022_Fellazio.png', 'La storia di Fel-Lazio nel Fanta a 20 è stata fin dall''inizio una continua lotta per difendere il proprio posto in Serie A. Presente sin dalla stagione inaugurale della competizione, il club ha sempre mantenuto la categoria nonostante diversi piazzamenti nelle zone basse della classifica. La retrocessione maturata al termine della stagione 2025/26 interrompe però questa permanenza, aprendo una nuova fase della sua storia. Dalla Serie B ripartirà con l''obiettivo di riconquistare rapidamente la massima categoria.', null, true),
  (23, 'Genoa Lang', null, public.normalize_societa_name('Genoa Lang'), 'Genoa', 'Gabriele Mantio', 'ilmanzio', '2023/24', 'Serie B', null, '/societa/023_Genoalang.png', 'Poche società hanno vissuto sbalzi così improvvisi come Genoa Lang. Presente nel Fanta a 20 fin dalla stagione inaugurale, il club raggiunge l''apice della propria storia nel 2024/25 conquistando uno storico Scudetto, che lo consacra tra le grandi della competizione. Solo una stagione più tardi, però, arriva l''inaspettata retrocessione in Serie B, una delle più sorprendenti nella storia del Fanta a 20. Dagli onori del titolo nazionale all''amarezza della caduta, il percorso di Genoa Lang racconta quanto questa competizione sappia essere imprevedibile.', null, true),
  (24, 'Bario Roggero', null, public.normalize_societa_name('Bario Roggero'), 'Bari', 'Davide Mangini - Carlo Gagliardi - Leonardo Rossi', '?', '2026/27', 'Serie B', null, '/societa/024_Barioruggero.png', 'Bario Ruggero raccoglie l''eredità di una società che ha saputo conquistare l''Europa League, primo trofeo internazionale della propria storia. Con il cambio di identità si apre però un nuovo capitolo: un progetto inedito, chiamato a costruire il proprio percorso senza dimenticare le fondamenta lasciate dal passato. Da oggi sarà Bario Ruggero a scrivere le prossime pagine della sua storia nel Fanta a 20, con l''obiettivo di arricchire un palmarès già inaugurato da un prestigioso successo europeo.', 'new_entry', true),
  (25, 'Licorto Muso FC', null, public.normalize_societa_name('Licorto Muso FC'), 'Livorno', 'Marian Szilagyi', 'rg.fra', '2025/26', 'Serie B', null, '/societa/025_Licortomuso.png', 'Entrata nel Fanta a 20 nella stagione 2025/26, Licorto Muso FC si è messa subito in luce con una stagione d''esordio di altissimo livello. Il secondo posto nel Girone B di Serie C le vale la promozione in Serie B come miglior seconda classificata, mentre il cammino fino alla finale di Coppa Fanta a 20 dimostra fin da subito la competitività del club anche nelle sfide più importanti. Una prima annata ricca di soddisfazioni, impreziosita anche dal raggiungimento delle fasi finali della Champions League, che pone basi solide per il futuro della società.', 'neo_promossa', true),
  (26, 'PalerMavai Ma vieni Ma chi sono', null, public.normalize_societa_name('PalerMavai Ma vieni Ma chi sono'), 'Palermo', 'Nicola Pazzi', 'nicolapazzi', '2023/24', 'Serie B', null, '/societa/026_Palermavaimavienimachisono.png', 'La storia di PalerMavai Ma vieni Ma chi sono nel Fanta a 20 inizia nel migliore dei modi. Presente fin dalla stagione inaugurale della competizione, il club sfiora immediatamente uno storico double chiudendo al secondo posto in Serie A e raggiungendo la finale di Champions League. Quello che sembrava l''inizio di un ciclo vincente si trasforma però in un percorso sempre più complicato, culminato con la retrocessione in Serie B al termine della stagione 2024/25. Dopo aver accarezzato il tetto del Fanta a 20, la società è ora chiamata a rilanciarsi per tornare protagonista.', null, true),
  (27, 'Andrea e Giugliano', null, public.normalize_societa_name('Andrea e Giugliano'), 'Giugliano', 'Davide Roma', 'davide_roma91', '2025/26', 'Serie B', null, '/societa/027_Andreaegiugliano.png', 'L''avventura di Andrea e Giugliano nel Fanta a 20 comincia nella stagione 2025/26 nel migliore dei modi. Al debutto il club conquista il Girone C di Serie C, centrando subito la promozione, e impreziosisce una stagione già straordinaria raggiungendo anche la finale di Champions League. Un esordio di grande spessore che ha permesso alla società di presentarsi immediatamente come una delle nuove protagoniste della competizione.', 'neo_promossa', true),
  (28, 'Ospitaletto', null, public.normalize_societa_name('Ospitaletto'), 'Ospitaletto', 'Alessandro Di Lonardo - Diego Rovito', 'als_dld', '2025/26', 'Serie B', null, '/societa/028_Ospitaletto.png', 'L''ingresso di Ospitaletto nel Fanta a 20 coincide con una stagione da ricordare. Al debutto assoluto il club conquista il Girone A di Serie C, ottenendo l''immediata promozione, e completa un''annata di grande livello raggiungendo anche la finale di Champions League. Un esordio convincente che gli ha permesso di affacciarsi alla competizione con ambizione e di entrare subito tra le società più promettenti del Fanta a 20.', 'neo_promossa', true),
  (29, 'PESCARAMUCCIA', null, public.normalize_societa_name('PESCARAMUCCIA'), 'Pescara', 'Francesco Deioia', 'francesco.deioia', '2024/25', 'Serie B', null, '/societa/029_Pescaramuccia.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, PESCARAMUCCIA ha saputo migliorarsi sensibilmente nel giro di una sola stagione. Dopo il tredicesimo posto ottenuto all''esordio, il club compie un deciso passo avanti chiudendo il campionato di Serie B al quinto posto e raggiungendo la finale di Europa League, primo grande traguardo internazionale della sua storia. Un''evoluzione che testimonia la crescita di una società sempre più competitiva e determinata a ritagliarsi un ruolo di primo piano nel Fanta a 20.', null, true),
  (30, 'Bacarpi Schitz', null, public.normalize_societa_name('Bacarpi Schitz'), 'Carpi', 'Angelo Convertini - Vito Punzi - Agostino Semeraro', 'angeloconvertini', '2025/26', 'Serie B', null, '/societa/030_Bacarpi.png', 'Esordire e vincere non è mai semplice, ma Bacarpi Schitz ci è riuscita subito.** Alla sua prima stagione nel Fanta a 20 il club conquista il Girone B di Serie C, centrando l''immediata promozione. Un''annata estremamente positiva, impreziosita anche dalla partecipazione alle fasi finali della Champions League, che ha permesso alla società di affacciarsi al panorama del Fanta a 20 con ambizione e risultati concreti.', 'neo_promossa', true),
  (31, 'Mantovai', null, public.normalize_societa_name('Mantovai'), 'Mantova', 'Andrea Marianelli - Edoardo Di Biasi', 'andreamarianelli', '2026/27', 'Serie B', null, '/societa/031_Mantovai.png', 'Mantovai fa il suo ingresso nel Fanta a 20 raccogliendo l''eredità sportiva della società che l''ha preceduta, di cui conserva il posto e il Ranking Storico. Da questa stagione prende però vita una nuova identità, chiamata a costruire il proprio percorso e ad arricchire una storia che, pur affondando le radici nel passato, è pronta a scrivere un capitolo completamente nuovo.', 'new_entry', true),
  (32, 'FROSILVIONE', null, public.normalize_societa_name('FROSILVIONE'), 'Frosinone', 'Silvestro Crugliano', 'silvio.crugliano00', '2024/25', 'Serie B', null, '/societa/032_Frosilvione.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, FROSILVIONE ha affrontato le prime due annate della propria storia costruendo basi sempre più solide. Dopo il quattordicesimo posto ottenuto all''esordio, il club migliora il proprio rendimento chiudendo l''annata successiva all''undicesimo posto in Serie B, accompagnando la crescita in campionato con una presenza nelle fasi finali dell''Europa League. Un percorso che racconta una società in costante evoluzione, determinata a ridurre progressivamente il divario dalle posizioni di vertice.', null, true),
  (33, 'Monzarella e Pomodoro', null, public.normalize_societa_name('Monzarella e Pomodoro'), 'Monza', 'Alessia Marianelli - Ettore Funaioli', 'alessiamarianelli - ettofuna', '2025/26', 'Serie B', null, '/societa/033_Monzarellaepomodoro.png', 'L''avventura di Monzarella e Pomodoro nel Fanta a 20 si apre con una stagione ricca di segnali positivi. Al debutto il club chiude il campionato di Serie B al quarto posto, sfiorando immediatamente la zona promozione e dimostrando di poter competere fin da subito con le migliori della categoria. Un esordio solido e convincente, che rappresenta un punto di partenza incoraggiante per la crescita della società.', null, true),
  (34, 'Juve Scabbia', null, public.normalize_societa_name('Juve Scabbia'), 'Juve Stabia', 'Francesco Ciciliano - Alberto Bonventre', 'el_cicio - el_paposky', '2024/25', 'Serie B', null, '/societa/034_Juvescabbia.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, Juve Scabbia ha vissuto un avvio di percorso fatto di luci e ombre. Dopo un ottavo posto ottenuto all''esordio, il club non è riuscito a confermarsi nella stagione successiva, chiudendo il campionato di Serie B al quindicesimo posto. Un inizio caratterizzato da risultati altalenanti, che lascia alla società il compito di ritrovare continuità per rilanciarsi nelle prossime stagioni.', null, true),
  (35, 'PadoVainCul', null, public.normalize_societa_name('PadoVainCul'), 'Padova', 'Isacco Giarola - Giovanni Coatti - Davide Allegri', 'isaccojm - allegridave - giovanni_coatti', '2024/25', 'Serie B', null, '/societa/035_Padovaincul.png', 'L''avventura di PadoVainCul nel Fanta a 20 è iniziata nella stagione 2024/25 con un esordio complicato, ma la risposta del club non si è fatta attendere. Nel giro di una sola stagione la società risale fino al settimo posto in Serie B, accompagnando la crescita in campionato con il raggiungimento della finale di Champions League, il miglior risultato internazionale della sua giovane storia. Un''evoluzione che testimonia la capacità del club di reagire alle difficoltà e costruire basi sempre più solide per il futuro.', null, true),
  (36, 'Spezial One', null, public.normalize_societa_name('Spezial One'), 'Spezia', 'Christope Dainelli - Alberto Colpo', 'piccolo_daino - alberto_colpo', '2024/25', 'Serie B', null, '/societa/036_Spezialone.png', 'I risultati in campionato non raccontano fino in fondo la storia di Spezial One. Entrata nel Fanta a 20 nella stagione 2024/25, la società ha vissuto due annate difficili in Serie B, senza riuscire a inserirsi nella lotta per le posizioni di vertice. Nonostante questo, è riuscita a conquistare la Conference League già al primo anno di partecipazione, sollevando il primo trofeo ufficiale della propria storia. Un successo che dimostra come il club abbia saputo lasciare il segno anche nei momenti più complicati del proprio percorso.', null, true),
  (37, 'Empoliticamente Scorretto', null, public.normalize_societa_name('Empoliticamente Scorretto'), 'Empoli', 'Dario Passaforte - Alfredo Manica', 'da.pass_ - alfredo__ma', '2024/25', 'Serie B', null, '/societa/037_Empoliticamentescorretto.png', 'L''esordio di Empoliticamente Scorretto nel Fanta a 20 è stato impreziosito da un successo destinato a entrare nella storia del club. Alla sua prima stagione la società conquista la Conference League, sollevando il primo trofeo ufficiale della propria storia e affiancando il trionfo europeo a un nono posto nel campionato di Serie B. Un debutto che ha permesso al club di inaugurare il proprio palmarès fin dal primo anno di partecipazione, ponendo basi interessanti per il prosieguo del progetto.', null, true),
  (38, 'CARTAnzaro', null, public.normalize_societa_name('CARTAnzaro'), 'Catanzaro', 'Paolo Ciampà', 'pist_ola', '2024/25', 'Serie B', null, '/societa/038_Cartanzaro.png', 'L''avventura di CARTAnzaro nel Fanta a 20 prende il via nella stagione 2025/26. Al primo anno di partecipazione il club conclude il campionato di Serie B al dodicesimo posto, vivendo un''annata di ambientamento utile a conoscere la competizione e a gettare le basi per il proprio percorso. Una prima esperienza che rappresenta il punto di partenza di una società ancora tutta da costruire.', null, true),
  (39, 'FC CESENARTICO', null, public.normalize_societa_name('FC CESENARTICO'), 'Cesena', 'Luigi Pantisano - Francesco Sottile', 'luigi.pantisanoc - don_sottils', '2025/26', 'Serie B', null, '/societa/039_Cesenartico.png', 'Per FC CESENARTICO il 2025/26 ha rappresentato l''inizio dell''avventura nel Fanta a 20. La società ha chiuso la sua prima stagione al decimo posto in Serie B, acquisendo esperienza in una competizione completamente nuova e gettando le basi per il proprio percorso. Un esordio che offre margini di crescita e da cui il club proverà a costruire le proprie ambizioni nelle stagioni future.', null, true),
  (40, 'Virtus Tavernello', null, public.normalize_societa_name('Virtus Tavernello'), 'Virtus Entella', 'Gianmarco Ghelardi', 'gianmarco_ghelardi', '2026/27', 'Serie B', null, '/societa/040_Virtusentella.png', 'Con il suo ingresso nel Fanta a 20, Virtus Tavernello apre un nuovo capitolo della propria storia. Pur ereditando il posto e il Ranking Storico della società che l''ha preceduta, il club nasce con un''identità completamente nuova, chiamata a costruire il proprio percorso e a lasciare un segno personale nella competizione. Da oggi sarà Virtus Tavernello a scrivere le prossime pagine della sua storia nel Fanta a 20.', 'new_entry', true),
  (41, 'Fc TiramiSudtirol', null, public.normalize_societa_name('Fc TiramiSudtirol'), 'Sud Tirol', 'Giovanni Tomelleri', '_tomeee', '2025/26', 'Serie C', 'A', '/societa/041_Tiramisudtirol.png', 'L''avventura di FC TiramiSudtirol nel Fanta a 20 prende il via nella stagione 2025/26 con un''annata ricca di difficoltà. Il diciottesimo posto in Serie B comporta l''immediata retrocessione in Serie C, costringendo il club a ripartire dalla categoria inferiore dopo una sola stagione. Un esordio complicato che rappresenta il primo banco di prova per una società chiamata a reagire e a costruire il proprio percorso nel Fanta a 20.', null, true),
  (42, 'LanaRhoades Vicenza', null, public.normalize_societa_name('LanaRhoades Vicenza'), 'Vicenza', 'Alessio Lazzeroni', 'ale.lazzee', '2025/26', 'Serie C', 'A', '/societa/042_Lrvicenza.png', 'Poche società possono vantare un ingresso nel Fanta a 20 come quello di LanaRhoades Vicenza. Al debutto nella stagione 2025/26 il club conquista la Coppa Fanta a 20, diventando immediatamente protagonista della competizione e iscrivendo il proprio nome nell''albo d''oro del trofeo più trasversale del Fanta a 20. Un successo di assoluto prestigio, ottenuto in una manifestazione che coinvolge tutte le cento società della lega, capace di consegnare fin da subito alla società il primo grande capitolo della propria storia.', null, true),
  (43, 'SCARENATE L INFERNO', null, public.normalize_societa_name('SCARENATE L INFERNO'), 'Renate', 'Giacomo Pettinato - Simone Massa', null, '2025/26', 'Serie C', 'A', '/societa/043_Scarenatelinferno.png', 'L''ingresso di SCARENATE L''INFERNO nel Fanta a 20 non è passato inosservato. Alla prima stagione il club chiude il Girone A di Serie C al terzo posto e conquista la Champions League, inaugurando il proprio palmarès con uno dei trofei più prestigiosi della competizione. Un esordio di altissimo livello che ha permesso alla società di lasciare subito un segno nella storia del Fanta a 20 e di presentarsi con grandi ambizioni.', null, true),
  (44, 'Ciolone Milano', null, public.normalize_societa_name('Ciolone Milano'), 'Alcione Milano', 'Stefano Franco - Marco Bigucci', 'ste_franco08', '2025/26', 'Serie C', 'A', '/societa/044_Ciolonemilano.png', 'L''esordio di Ciolone Milano nel Fanta a 20 è stato impreziosito da un risultato che poche società possono vantare. Alla prima partecipazione il club chiude il Girone A di Serie C al quarto posto, ma soprattutto conquista il primo posto assoluto nel girone di qualificazione della Coppa Fanta a 20, precedendo tutte le cento società partecipanti alla competizione. Un traguardo che testimonia il potenziale mostrato fin dal debutto e rappresenta una delle pagine più significative della giovane storia del club.', null, true),
  (45, 'El Dolomitazo', null, public.normalize_societa_name('El Dolomitazo'), 'Dolomiti', 'Andrea Codega', 'endriuco', '2025/26', 'Serie C', 'A', '/societa/045_Eldolomitazo.png', 'Entrata nel Fanta a 20 nella stagione 2025/26, El Dolomitazo ha saputo mettersi subito in evidenza con un campionato di alto livello. Il secondo posto conquistato nel Girone A di Serie C le ha permesso di sfiorare la promozione già al primo tentativo, confermando fin da subito la competitività del progetto. Un esordio solido e convincente, che lascia intravedere le ambizioni di una società pronta a recitare un ruolo importante nelle stagioni future.', null, true),
  (46, 'CITTASNELLA', null, public.normalize_societa_name('CITTASNELLA'), 'Cittadella', 'Francesco Ferraro', 's_k_i_n__22', '2025/26', 'Serie C', 'A', '/societa/046_Cittasnella.png', 'L''esordio di CITTASNELLA nel Fanta a 20 è stato caratterizzato da un campionato solido e competitivo. Alla prima partecipazione il club chiude il Girone A di Serie C al quinto posto, rimanendo per tutta la stagione a contatto con le squadre di vertice. Una prima annata positiva, che ha permesso alla società di gettare basi importanti e di affacciarsi alla competizione con prospettive incoraggianti.', null, true),
  (47, 'Virtual Verona', null, public.normalize_societa_name('Virtual Verona'), 'Virtus Verona', 'Niccolò Canavesi', 'nico_cana_02', '2025/26', 'Serie C', 'A', '/societa/047_Virtualverona.png', 'Virtual Verona si affaccia al Fanta a 20 nella stagione 2025/26, inaugurando il proprio percorso nella competizione. Il decimo posto ottenuto nel Girone A di Serie C rappresenta il primo tassello della storia del club, maturato in un''annata utile ad acquisire esperienza e a misurarsi con le dinamiche del campionato. Un punto di partenza da cui la società proverà a costruire le proprie ambizioni nelle stagioni a venire.', null, true),
  (48, 'Albionoleffe', null, public.normalize_societa_name('Albionoleffe'), 'Albinoleffe', 'Emilio Tirozzi', 'emilio_tirozzi', '2025/26', 'Serie C', 'A', '/societa/048_Albionoleffe.png', 'L''avventura di Brighton & Hove Albionoleffe nel Fanta a 20 prende il via nella stagione 2025/26 con un campionato solido e ricco di spunti positivi. Il settimo posto conquistato nel Girone A di Serie C permette alla società di chiudere il proprio anno d''esordio a ridosso della prima metà della classifica, ponendo basi interessanti per il futuro. Un primo passo che offre al club l''opportunità di continuare a crescere e consolidarsi nelle stagioni successive.', null, true),
  (49, 'AS Giana Erminio', null, public.normalize_societa_name('AS Giana Erminio'), 'As Giana Erminio', 'Luca Leone - Vincenzo Ricci', null, '2026/27', 'Serie C', 'A', '/societa/049_Gianaerminio.png', 'Con l''arrivo di AS Giana Erminio prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club inaugura un percorso completamente nuovo, chiamato a costruire una tradizione propria e ad aggiungere nuove pagine alla storia della competizione. Da oggi sarà AS Giana Erminio a dare continuità a quell''eredità, cercando di trasformarla in una storia tutta sua.', 'new_entry', true),
  (50, 'Lecco Benfica', null, public.normalize_societa_name('Lecco Benfica'), 'Lecco', 'Luca Pescatori', '249423er', '2026/27', 'Serie C', 'A', '/societa/050_Leccobenfica.png', 'Con l''arrivo di Lecco Benfica prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club eredita anche un palmarès già impreziosito dalla conquista dell''Europa League. Da oggi, però, si apre un capitolo completamente nuovo: sarà Lecco Benfica a dare continuità a questa eredità, costruendo il proprio percorso e scrivendo una storia tutta sua.', 'new_entry', true),
  (51, 'Communion Brescia', null, public.normalize_societa_name('Communion Brescia'), 'Brescia', 'Giuliano Vielmi', 'giuliano.vielmi', '2025/26', 'Serie C', 'A', '/societa/051_Communionbrescia.png', 'L''esordio di Communion Brescia nel Fanta a 20 è stato segnato da un record destinato a entrare nella storia della competizione. Alla prima stagione il club chiude il Girone A di Serie C al nono posto, ma si distingue soprattutto conquistando l''emblema Mercante grazie a ben 21 scambi effettuati in un''unica annata, primato assoluto nella storia del Fanta a 20. Un risultato che racconta la filosofia di una società estremamente attiva sul mercato, capace di lasciare subito il proprio segno con un record destinato a rimanere negli albi d''oro.', null, true),
  (52, 'Aurora Pro Patriarcato', null, public.normalize_societa_name('Aurora Pro Patriarcato'), 'Aurora Pro Patria', 'Federico Spilotros', 'lorenzo.xlsx', '2025/26', 'Serie C', 'A', '/societa/052_Aurorapropatriarcato.png', 'L''esordio di Aurora Pro Patriarcato nel Fanta a 20 coincide con la stagione 2025/26. Il club conclude il proprio primo campionato al quindicesimo posto nel Girone A di Serie C, vivendo un''annata utile ad acquisire esperienza e a prendere confidenza con la competizione. Un primo capitolo che offre alla società le basi su cui costruire il proprio percorso nelle stagioni future.', null, true),
  (53, 'next Gengis Khan', null, public.normalize_societa_name('next Gengis Khan'), 'Juventus Next Gen', 'Mattia Fava - Nicolò Fossà', 'favamattia - nicolo_fossa_', '2025/26', 'Serie C', 'A', '/societa/053_Nextgenigskhan.png', 'L''esordio di next Gengis Khan nel Fanta a 20 ha raccontato due facce della stessa stagione. Se in campionato il club ha chiuso al quattordicesimo posto nel Girone A di Serie C, nelle competizioni europee è riuscito a spingersi fino alla finale di Europa League, centrando il primo grande traguardo internazionale della propria storia. Un debutto che ha mostrato fin da subito la capacità della società di mettersi in evidenza nei grandi appuntamenti.', null, true),
  (54, 'Pro VercHell', null, public.normalize_societa_name('Pro VercHell'), 'Pro Vercelli', 'Leonardo Falconi', null, '2026/27', 'Serie C', 'A', '/societa/054_Proverchell.png', 'Con l''arrivo di Pro Verchell prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club inaugura un percorso completamente nuovo, chiamato a costruire una tradizione propria e a lasciare il proprio segno nella competizione. Da oggi sarà Pro Verchell a dare continuità a questa eredità, scrivendo una storia tutta sua.', 'new_entry', true),
  (55, 'Triest-In Peace', null, public.normalize_societa_name('Triest-In Peace'), 'Triestina', 'Daniele Cuntrera - Gabriele Muratore', 'dancun19', '2025/26', 'Serie C', 'A', '/societa/055_Triestinpeace.png', 'La storia di Triest-In Peace nel Fanta a 20 prende il via nella stagione 2025/26. Al debutto il club conclude il Girone A di Serie C al dodicesimo posto, vivendo un''annata di ambientamento che gli ha permesso di confrontarsi per la prima volta con la competizione. Un primo capitolo che rappresenta l''inizio del percorso della società, chiamata a costruire la propria identità stagione dopo stagione.', null, true),
  (56, 'FC Arzignano VAcchiappo', null, public.normalize_societa_name('FC Arzignano VAcchiappo'), 'Arzignano Valchiampo', 'Raffaele Picci', 'raffaelepicci_', '2025/26', 'Serie C', 'A', '/societa/056_Arzignanovacchiappo.png', 'Il percorso di FC Arzignano VAcchiappo nel Fanta a 20 inizia nella stagione 2025/26. Al debutto il club conclude il Girone A di Serie C al sedicesimo posto, affrontando un''annata utile a prendere confidenza con una competizione del tutto nuova. Un primo capitolo che offre alla società l''occasione di accumulare esperienza e di porre le basi per la propria crescita nelle stagioni future.', null, true),
  (57, 'Lumezzanegger', null, public.normalize_societa_name('Lumezzanegger'), 'Lumezzane', 'Alessandro Zecca - Alessio De Falco', 'ale.zecca_ - the.defa', '2026/27', 'Serie C', 'A', '/societa/057_Lumezzanegger.png', 'Con l''arrivo di Lumezzanegger prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club inaugura un percorso completamente nuovo, chiamato a costruire una tradizione propria e a lasciare il proprio segno nella competizione. Da oggi sarà Lumezzanegger a dare continuità a questa eredità, scrivendo una storia tutta sua.', 'new_entry', true),
  (58, 'Novar', null, public.normalize_societa_name('Novar'), 'Novara', 'Francesco Panattoni', 'insta_pana', '2026/27', 'Serie C', 'A', '/societa/058_Novar.png', 'Con l''arrivo di NO-VAR prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club inaugura un percorso completamente nuovo, chiamato a costruire una tradizione propria e a lasciare il proprio segno nella competizione. Da oggi sarà NO-VAR a dare continuità a questa eredità, scrivendo una storia tutta sua.', 'new_entry', true),
  (59, 'PergoleTette', null, public.normalize_societa_name('PergoleTette'), 'Pergolettese', 'Alber Rrushkulli - Gianluca Sestigiani', 'pdor__ - p1alluz', '2025/26', 'Serie C', 'A', '/societa/059_Pergoletette.png', 'L''esordio di PergoleTette nel Fanta a 20 dimostra come una stagione possa essere ricordata ben oltre il piazzamento in campionato. Alla prima partecipazione il club chiude il Girone A di Serie C al diciottesimo posto, ma riesce comunque a conquistare la Conference League, sollevando il primo trofeo ufficiale della propria storia. Un successo che consegna immediatamente la società all''albo d''oro della competizione e rappresenta il primo grande traguardo del suo percorso nel Fanta a 20.', null, true),
  (60, 'Trento La Fortuna', null, public.normalize_societa_name('Trento La Fortuna'), 'Trento', 'Lorenzo Marinoni', 'lore_goblub', '2026/27', 'Serie C', 'A', '/societa/060_Trentolafortuna.png', 'Con l''arrivo di Trento la fortuna prende vita una nuova identità nel Fanta a 20. Pur raccogliendo il posto e il Ranking Storico della società che l''ha preceduta, il club inaugura un percorso completamente nuovo, chiamato a costruire una tradizione propria e a lasciare il proprio segno nella competizione. Da oggi sarà Trento la fortuna a dare continuità a questa eredità, scrivendo una storia tutta sua.', 'new_entry', true),
  (61, 'AGNELLINO', null, public.normalize_societa_name('AGNELLINO'), 'Avellino', 'Pierluigi Anania', 'pierluigianania', '2025/26', 'Serie C', 'B', '/societa/061_Agnellino.png', 'L''avventura di AGNELLINO nel Fanta a 20 inizia nella stagione 2025/26 con un''annata ricca di ostacoli. Il diciannovesimo posto in Serie B comporta l''immediata retrocessione in Serie C, costringendo il club a ripartire dalla categoria inferiore dopo una sola stagione. Un esordio difficile che rappresenta il primo capitolo della storia della società, chiamata ora a reagire e a costruire il proprio percorso nel Fanta a 20.', null, true),
  (62, 'FORLIPPO INZAGHI', null, public.normalize_societa_name('FORLIPPO INZAGHI'), 'Forlì', 'Corrado Salvemini - Nicola Pizzolorusso', 'corrado_salvemini99', '2025/26', 'Serie C', 'B', '/societa/062_Forlippoinzaghi.png', 'L''ingresso di FORLIPPO INZAGHI nel Fanta a 20 è stato impreziosito da un successo di grande prestigio. Alla prima stagione il club chiude il Girone B di Serie C al terzo posto e conquista la Champions League, inaugurando il proprio palmarès con uno dei trofei più importanti della competizione. Un esordio di alto livello che ha permesso alla società di lasciare immediatamente il proprio segno nel Fanta a 20.', null, true),
  (63, 'Campobasta', null, public.normalize_societa_name('Campobasta'), 'Campobasso', 'Matteo Colibazzi', 'matteo_c24', '2025/26', 'Serie C', 'B', '/societa/063_Campobasta.png', 'L''avventura di Campobasta nel Fanta a 20 prende il via con una stagione ricca di segnali positivi. Al debutto il club chiude il Girone B di Serie C al quarto posto, restando a ridosso della zona promozione, e impreziosisce la propria annata raggiungendo la finale di Champions League. Un esordio convincente che ha permesso alla società di mettersi subito in evidenza e di porre basi solide per il proprio futuro.', null, true),
  (64, 'PONTEDERA', null, public.normalize_societa_name('PONTEDERA'), 'Pontedera', 'Mattia Don - Luca Colombo - Nicolò Spreafico', 'mattiaadon', '2025/26', 'Serie C', 'B', '/societa/064_Pontedera.png', 'Il primo capitolo della storia di PONTEDERA nel Fanta a 20 coincide con la stagione 2025/26. Al debutto il club chiude il Girone B di Serie C al quinto posto, disputando un campionato competitivo e rimanendo a breve distanza dalle posizioni di vertice. Un esordio incoraggiante che offre alla società basi solide su cui continuare a costruire il proprio percorso nella competizione.', null, true),
  (65, 'GubbioDSQ', null, public.normalize_societa_name('GubbioDSQ'), 'Gubbio', 'Gabriele Madeo - Federico Di Vito', 'gabb._io - federico.divito', '2025/26', 'Serie C', 'B', '/societa/065_Gubbiodsq.png', 'L''avventura di Gubbio DSQ nel Fanta a 20 prende il via nella stagione 2025/26. Alla prima partecipazione il club conclude il Girone B di Serie C all''ottavo posto, affrontando un''annata utile a prendere confidenza con la competizione e con le sue dinamiche. Un primo campionato che rappresenta il punto di partenza di una società chiamata a costruire, stagione dopo stagione, la propria identità nel Fanta a 20.', null, true),
  (66, 'Ravengers FC', null, public.normalize_societa_name('Ravengers FC'), 'Ravenna', 'Edoardo Vallone - Paolo Varbaro', 'edo.vallone', '2025/26', 'Serie C', 'C', '/societa/066_Ravengers.png', 'L''esordio di Ravengers FC nel Fanta a 20 è stato impreziosito da un trionfo destinato a entrare nella storia del club. Alla prima stagione la società conquista l''Europa League, sollevando il primo trofeo ufficiale del proprio palmarès e iscrivendo immediatamente il proprio nome nell''albo d''oro della competizione. Un successo di grande prestigio che rende memorabile l''annata d''esordio, ben oltre il settimo posto ottenuto nel Girone B di Serie C.', null, true),
