  (79, 'NasPicerno', null, public.normalize_societa_name('NasPicerno'), 'Picerno', 'Matthew Spinello - Andrea Longoni', 'matthewspinello', '2025/26', 'Serie C', 'B', '/societa/079_Naspicerno.png', 'L''avventura di NasPicerno nel Fanta a 20 prende il via con una stagione ricca di segnali positivi. Al debutto il club chiude il Girone C di Serie C al quinto posto, disputando un campionato competitivo e rimanendo a contatto con le posizioni di vertice. Un esordio convincente che ha permesso alla società di gettare basi solide e di affacciarsi alla competizione con ambizioni importanti.', null, true),
  (80, 'SiracUSA', null, public.normalize_societa_name('SiracUSA'), 'Siracusa', 'Riccardo Cesaretti - Riccardo Zappatori - Jacopo Verdini - Nicolò Ramazzotti', 'riccardo_cesaretti8', '2025/26', 'Serie C', 'B', '/societa/080_Siracusa.png', 'La storia di SiracUSA nel Fanta a 20 inizia nella stagione 2025/26. Al debutto il club conclude il Girone C di Serie C al sedicesimo posto, vivendo un''annata utile a confrontarsi per la prima volta con la competizione e ad accumulare esperienza. Un primo capitolo che rappresenta il punto di partenza di un percorso ancora tutto da scrivere.', null, true),
  (81, 'Sampdodoria', null, public.normalize_societa_name('Sampdodoria'), 'Sampdoria', 'Federico Sbarra', 'furfe94', '2024/25', 'Serie C', 'C', '/societa/081_Sampdodoria.png', 'Entrata nel Fanta a 20 nella stagione 2024/25, Sampdodoria ha vissuto un percorso fatto di luci e ombre. Se in campionato il club è passato dal decimo posto in Serie B alla retrocessione in Serie C nella stagione successiva, nelle competizioni europee ha saputo ritagliarsi un ruolo da protagonista raggiungendo prima la finale di Europa League e poi quella di Conference League. Due traguardi che rappresentano i risultati più prestigiosi della giovane storia della società e testimoniano una particolare attitudine nelle competizioni internazionali.', null, true),
  (82, 'Sambenedetta Domenica', null, public.normalize_societa_name('Sambenedetta Domenica'), 'Sambenedettese', 'Alessio D''Errico - Gianluca Stabile', null, '2025/26', 'Serie C', 'C', '/societa/082_Sambenedettadomenica.png', 'L''avventura di Sambenedetta Domenica nel Fanta a 20 prende il via nella stagione 2025/26 con un campionato convincente. Al debutto il club chiude il Girone B di Serie C al sesto posto, rimanendo a breve distanza dalle posizioni di vertice e mostrando fin da subito una buona competitività. Un primo anno incoraggiante che offre alla società solide fondamenta su cui continuare a costruire il proprio percorso.', null, true),
  (83, 'Cassarano', null, public.normalize_societa_name('Cassarano'), 'Casarano', 'Davide Schiavone - Matteo Modolo', 'davide_schiavon3', '2025/26', 'Serie C', 'C', '/societa/083_Cassarano.png', 'L''avventura di Cassarano nel Fanta a 20 si apre con una stagione ricca di buoni segnali. Al debutto il club conclude il Girone C di Serie C all''ottavo posto, ma il risultato più prestigioso arriva in Coppa Fanta a 20, dove conquista il terzo posto assoluto al termine di un percorso di grande livello. Un esordio convincente che ha permesso alla società di mettersi subito in evidenza in una competizione che coinvolge tutte le cento squadre del Fanta a 20.', null, true),
  (84, 'Monopoly', null, public.normalize_societa_name('Monopoly'), 'Monopoli', 'Nicolò Fava - Ettore Scarcia', null, '2025/26', 'Serie C', 'C', '/societa/084_Monopoly.png', 'L''ingresso di Monopoly nel Fanta a 20 è stato accompagnato da un campionato di alto livello. Alla prima stagione il club conquista il terzo posto nel Girone C di Serie C, sfiorando fin da subito la promozione e dimostrando di poter competere con le migliori della categoria. Un esordio convincente che rappresenta un''ottima base su cui costruire il futuro della società.', null, true),
  (85, 'Croton Fioc', null, public.normalize_societa_name('Croton Fioc'), 'Crotone', 'Antonio De Maio', 'ninodemaio_', '2025/26', 'Serie C', 'C', '/societa/085_Crotonfioc.png', 'L''esordio di Croton Fioc nel Fanta a 20 è stato subito all''altezza delle aspettative. Alla prima partecipazione il club chiude il Girone C di Serie C al secondo posto, sfiorando la vittoria del campionato e la promozione già al primo tentativo. Un debutto di grande solidità che ha permesso alla società di presentarsi immediatamente tra le realtà più competitive della categoria.', null, true),
